long long geometricSum(long long n, long long a1, long long d) {
    if (n == 0) return 0;
    long long num = (a1 % MOD) * ((ksm(d, n) - 1 + MOD) % MOD) % MOD;
    long long den = (d - 1 + MOD) % MOD;
    return num * inv(den) % MOD;
}

